                            var cur = peakSum.GetValueOrDefault(r, NatStar.Of(0));
                            var sub = c.Size.Hi.Value * e.Loop.Count.Value;
                            peakSum[r] = NatStar.Of(sub > cur.Value ? 0UL : cur.Value - sub);
